
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_fr_pw86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_fr_pw86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.410332445936606e+01, 9.046503633722938e+01, 8.549104488639918e+01, 7.883998140117338e+01, 7.022354964918944e+01, 5.955232404675308e+01, 4.714846332420301e+01, 3.394432606533825e+01, 2.146552457524895e+01, 1.141260656637096e+01, 5.026238632248290e+00, 2.533026819590101e+00, 1.906373346690525e+00, 1.272464812097866e+00, 6.471134462467225e-01, 2.402058649479325e-01, 6.089720600644669e-02, 9.505283291637526e-03, 7.752825481817288e-04, 2.314816315909942e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


